      lb.innerHTML = `<img src="${R2_CDN}assets/comics/${code}.jpg" alt="Comic zum Subtyp ${code}" style="max-width:100%;max-height:100vh;border-radius:0.5rem;box-shadow:0 8px 40px rgba(0,0,0,0.6);filter:contrast(1.08);" />`;
