// ---------------------------------------------------------------------------
// Enneagramm-Memory: Merkspiel auf Basis der Portr\u00e4t-Fotos. Zieht automatisch
// aus allen Portr\u00e4t-Registern (musterradarAllPortraits()) \u2013 jedes neue
// Portr\u00e4t vergr\u00f6\u00dfert damit von selbst den Kartenpool, keine manuelle Pflege
// n\u00f6tig. Drei Schwierigkeitsstufen (level 1/2/3), die definieren, wie fein
// ein "Paar" erkannt werden muss:
//   Level 1 (Anf\u00e4nger):      nur der Grundtyp (1\u20139) muss \u00fcbereinstimmen
//   Level 2 (Fortgeschritten): Grundtyp + Fl\u00fcgel m\u00fcssen \u00fcbereinstimmen
//   Level 3 (Experte):       vollst\u00e4ndiger Subtyp (Instinkt+Typ+Fl\u00fcgel)
// Getippt wird rein nach Gesicht/Blickqualit\u00e4t, kein Name w\u00e4hrend der
// Merkphase sichtbar. Nach jeder Rundenaufl\u00f6sung lassen sich alle neun
// Karten der Runde antippen, um Name + Typ jeder einzelnen Person zu sehen.
// ---------------------------------------------------------------------------

const MEMORY_TOTAL_ROUNDS = 10;
const MEMORY_MEMORIZE_MS = 60000;
const MEMORY_LEVEL_META = {
  1: { label: "Enneagramm-Memory I", sub: "Anf\u00e4nger \u00b7 nur der Grundtyp z\u00e4hlt",
       rule: "Zwei Karten bilden ein Paar, wenn sie zum selben <strong>Grundtyp (1&ndash;9)</strong> geh\u00f6ren &ndash; Instinktvariante und Fl\u00fcgel spielen keine Rolle. Beispiel: <strong>SO3</strong> und <strong>SX3</strong> z\u00e4hlen als Paar, weil beide Typ 3 sind." },
  2: { label: "Enneagramm-Memory II", sub: "Fortgeschrittene \u00b7 Grundtyp + Fl\u00fcgel",
       rule: "Zwei Karten bilden ein Paar, wenn <strong>Grundtyp UND Fl\u00fcgel</strong> \u00fcbereinstimmen &ndash; die Instinktvariante (SE/SO/SX) spielt keine Rolle. Beispiel: <strong>SE4w3</strong> und <strong>SX4w3</strong> z\u00e4hlen als Paar, weil beide 4w3 sind." },
  3: { label: "Enneagramm-Memory III", sub: "Experte \u00b7 vollst\u00e4ndiger Subtyp (Instinkt+Typ+Fl\u00fcgel)",
       rule: "Zwei Karten bilden nur dann ein Paar, wenn der <strong>komplette Subtyp inklusive Instinktvariante und Fl\u00fcgel</strong> exakt \u00fcbereinstimmt. Beispiel: Nur zwei Portr\u00e4ts mit exakt <strong>SO1w9</strong> bilden ein Paar &ndash; SE1w9 z\u00e4hlt nicht dazu." },
};

let _memoryState = null;
let _memoryLastLevel = 1;
const _memoryImgCache = {};

async function _memoryImgFor(route) {
  if (_memoryImgCache[route] !== undefined) return _memoryImgCache[route];
  let src = null;
  let pending = false;
  // Portr\u00e4tseiten werden lazy geladen: beim ersten Aufruf kommt nur der
  // Platzhalter. Dann auf das Laden warten und erneut lesen, statt "kein Bild"
  // zu cachen. _currentRoute wird kurz geleert, damit kein Re-Render ausgel\u00f6st wird.
  for (let attempt = 0; attempt < 2; attempt++) {
    pending = false;
    const savedRoute = window._currentRoute;
    try {
      const fn = ROUTES[route];
      if (fn) {
        window._currentRoute = null;
        const html = fn();
        const m = html.match(/<img\s+src="([^"]+)"[^>]*class="krim-portrait-img"/);
        if (m) { src = m[1]; break; }
        if (html.indexOf("suche-hint") !== -1) pending = true;
      }
    } catch (e) {} finally { window._currentRoute = savedRoute; }
    if (!pending) break;
    await Promise.all([..._lazyMods.values()].map(r => r.p).filter(Boolean));
  }
  if (src || !pending) _memoryImgCache[route] = src;
  return src;
}

const _memoryImgValidCache = {};
function _memoryValidateImg(src) {
  if (_memoryImgValidCache[src] !== undefined) return Promise.resolve(_memoryImgValidCache[src]);
  return new Promise(resolve => {
    const img = new Image();
    img.onload = () => { _memoryImgValidCache[src] = true; resolve(true); };
    img.onerror = () => { _memoryImgValidCache[src] = false; resolve(false); };
    img.src = src;
  });
}

function _memoryGroupKey(subtyp, level) {
  const p = musterradarParseSubtyp(subtyp);
  if (!p) return null;
  if (level === 1) return "T" + p.typ;
  if (level === 2) return p.wing ? ("T" + p.typ + "W" + p.wing) : null;
  return p.instinct + p.typ + (p.wing ? "W" + p.wing : "");
}

function _memoryCardLabel(subtyp, level) {
  const p = musterradarParseSubtyp(subtyp);
  if (!p) return (subtyp || "").toUpperCase();
  if (level === 1) return "Typ " + p.typ;
  if (level === 2) return p.typ + (p.wing ? "w" + p.wing : "");
  return (subtyp || "").toUpperCase();
}

function _memoryBuildPools(level) {
  const all = [...BERUEHMT_PORTRAITS, ...KRIMINAL_PORTRAITS].filter(p => p.subtyp && p.route);
  const byKey = {};
  all.forEach(p => {
    const key = _memoryGroupKey(p.subtyp, level);
    if (!key) return;
    (byKey[key] = byKey[key] || []).push(p);
  });
  return byKey;
}

function _memoryShuffle(arr) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

async function _memoryFindValidPortrait(candidates, usedRoutes) {
  for (const p of candidates) {
    if (usedRoutes.has(p.route)) continue;
    const img = await _memoryImgFor(p.route);
    if (!img) continue;
    const ok = await _memoryValidateImg(img);
    if (ok) return { route: p.route, subtyp: p.subtyp, name: p.name, img };
  }
  return null;
}

async function _memoryPickRound(level) {
  const pools = _memoryBuildPools(level);
  const pairKeys = _memoryShuffle(Object.keys(pools).filter(c => pools[c].length >= 2));
  if (!pairKeys.length) return null;

  // Jedes Foto wird vorab geladen und gepr\u00fcft \u2013 nur best\u00e4tigt funktionierende
  // Bilder landen auf einer Karte. Klappt ein Paar oder genug Distraktoren mit
  // dem gew\u00e4hlten Schl\u00fcssel nicht, wird der n\u00e4chste Schl\u00fcssel probiert.
  for (const pairKey of pairKeys) {
    const usedRoutes = new Set();
    const pairShuffled = _memoryShuffle(pools[pairKey]);
    const validPair = [];
    for (const p of pairShuffled) {
      if (validPair.length >= 2) break;
      const found = await _memoryFindValidPortrait([p], usedRoutes);
      if (found) { validPair.push(found); usedRoutes.add(found.route); }
    }
    if (validPair.length < 2) continue;

    const otherKeys = _memoryShuffle(Object.keys(pools).filter(c => c !== pairKey));
    const distractors = [];
    for (const key of otherKeys) {
      if (distractors.length >= 7) break;
      const found = await _memoryFindValidPortrait(_memoryShuffle(pools[key]), usedRoutes);
      if (found) { distractors.push(found); usedRoutes.add(found.route); }
    }
    if (distractors.length < 7) continue;

    const cards = _memoryShuffle([...validPair, ...distractors]).slice(0, 9);
    const pairRoutes = new Set(validPair.map(p => p.route));
    return { cards, pairRoutes, pairKey };
  }
  return null;
}

function _memoryRerender() {
  if (location.hash === "#enneagramm-memory") { render(); } else { location.hash = "enneagramm-memory"; }
}

function _memoryBestKey(level) { return "kompass:memoryBest:" + level; }

function _memorySaveBest(level, score) {
  try {
    const prev = parseInt(localStorage.getItem(_memoryBestKey(level)) || "0", 10);
    if (score > prev) localStorage.setItem(_memoryBestKey(level), String(score));
  } catch (e) {}
}

function _memoryGetBest(level) {
  try { return parseInt(localStorage.getItem(_memoryBestKey(level)) || "0", 10); } catch (e) { return 0; }
}

async function _memoryNextRound() {
  const st = _memoryState;
  if (!st) return;
  st.round += 1;
  if (st.round > MEMORY_TOTAL_ROUNDS) {
    st.phase = "gameOver";
    _memorySaveBest(st.level, st.score);
    _memoryRerender();
    return;
  }
  st.phase = "roundLoading";
  _memoryRerender();
  const roundData = await _memoryPickRound(st.level);
  if (_memoryState !== st) return; // Spiel wurde inzwischen neu gestartet/verlassen
  if (!roundData) { st.phase = "gameOver"; _memoryRerender(); return; }
  st.cards = roundData.cards;
  st.pairRoutes = roundData.pairRoutes;
  st.selected = [];
  st.revealed = [];
  st.resolution = null;
  st.phase = "memorize";
  _memoryRerender();
  if (st._timer) clearTimeout(st._timer);
  st._timer = setTimeout(() => {
    if (_memoryState === st && st.phase === "memorize") {
      st.phase = "guess";
      _memoryRerender();
    }
  }, MEMORY_MEMORIZE_MS);
}

window._memoryStart = function (level) {
  const lvl = MEMORY_LEVEL_META[level] ? level : 1;
  _memoryLastLevel = lvl;
  _memoryState = { level: lvl, phase: "loading", round: 0, score: 0, cards: [], pairRoutes: new Set(), selected: [], revealed: [], resolution: null };
  _memoryNextRound();
};

window._memorySwitchLevel = function (level) {
  const lvl = MEMORY_LEVEL_META[level] ? level : 1;
  _memoryLastLevel = lvl;
  _memoryState = null;
  _memoryRerender();
};

window._memoryPick = function (idx) {
  const st = _memoryState;
  if (!st || st.phase !== "guess") return;
  if (st.selected.includes(idx)) {
    st.selected = st.selected.filter(i => i !== idx);
    _memoryRerender();
    return;
  }
  if (st.selected.length >= 2) return;
  st.selected.push(idx);
  if (st.selected.length === 2) {
    const [a, b] = st.selected;
    const correct = st.pairRoutes.has(st.cards[a].route) && st.pairRoutes.has(st.cards[b].route);
    const correctIdxs = st.cards.map((c, i) => st.pairRoutes.has(c.route) ? i : -1).filter(i => i >= 0);
    st.resolution = { correct, correctIdxs };
    if (correct) st.score += 1;
    st.phase = "roundResult";
    if (st._timer) clearTimeout(st._timer);
  }
  _memoryRerender();
};

window._memoryReveal = function (idx) {
  const st = _memoryState;
  if (!st || st.phase !== "roundResult") return;
  if (!st.revealed.includes(idx)) {
    st.revealed = [...st.revealed, idx];
    _memoryRerender();
  }
};

window._memoryNextRound = function () { _memoryNextRound(); };
window._memoryRestart = function () {
  const lvl = _memoryState ? _memoryState.level : 1;
  window._memoryStart(lvl);
};

function _memoryCardHtml(card, i, st) {
  const isMemorize = st.phase === "memorize";
  const isSelected = st.selected.includes(i);
  const isResult = st.phase === "roundResult";
  const isCorrectCard = isResult && st.resolution.correctIdxs.includes(i);
  const isWrongPick = isResult && st.selected.includes(i) && !isCorrectCard;
  const isRevealed = isResult && st.revealed.includes(i);
  const open = isMemorize || isSelected || isCorrectCard || isRevealed;
  let stateClass = "";
  if (isResult) {
    if (isCorrectCard) stateClass = " mem-card--correct";
    else if (isWrongPick) stateClass = " mem-card--wrong";
  } else if (isSelected) {
    stateClass = " mem-card--selected";
  }
  const clickable = st.phase === "guess" || (isResult && !open);
  let onclick = "";
  if (st.phase === "guess") onclick = ` onclick="window._memoryPick(${i})"`;
  else if (isResult && !open) onclick = ` onclick="window._memoryReveal(${i})"`;
  const caption = (isResult && open)
    ? `<div class="mem-card-caption">${card.name} &middot; ${_memoryCardLabel(card.subtyp, st.level)}</div>`
    : "";
  return `
    <div class="mem-card${open ? " mem-card--open" : ""}${stateClass}"${onclick} role="button" aria-label="Karte ${i + 1}">
      <div class="mem-card-inner">
        <div class="mem-card-face mem-card-face--back">
          <span class="mem-card-mark">\u2726</span>
        </div>
        <div class="mem-card-face mem-card-face--front">
          <img src="${card.img}" alt="" loading="lazy" onerror="this.closest('.mem-card').classList.add('mem-card--broken');this.style.display='none';" />
          ${caption}
        </div>
      </div>
    </div>
  `;
}

function _memoryLevelSwitcher(currentLevel) {
  const items = [1,2,3].map(l => {
    const active = l === currentLevel;
    return active
      ? `<span class="mem-level-pill mem-level-pill--active">${l===1?"I":l===2?"II":"III"}</span>`
      : `<a href="javascript:void(0)" class="mem-level-pill" onclick="window._memorySwitchLevel(${l})">${l===1?"I":l===2?"II":"III"}</a>`;
  }).join("");
  return `<div class="mem-level-switcher"><span class="mem-level-switcher-label">Stufe:</span>${items}</div>`;
}

function _memoryStyles() {
  return `
    <style>
      .mem-grid { display:grid; grid-template-columns:repeat(3,1fr); gap:0.7rem; max-width:420px; margin:1.2rem auto; }
      .mem-card { aspect-ratio:1/1; perspective:900px; cursor:default; }
      .mem-card[role="button"] { cursor:pointer; }
      .mem-card-inner { position:relative; width:100%; height:100%; transform-style:preserve-3d; transition:transform .5s cubic-bezier(.4,.2,.2,1); border-radius:12px; }
      .mem-card--open .mem-card-inner { transform:rotateY(180deg); }
      .mem-card-face { position:absolute; inset:0; backface-visibility:hidden; border-radius:12px; overflow:hidden; display:flex; align-items:center; justify-content:center; }
      .mem-card-face--back { background:linear-gradient(135deg, var(--copper,#a5603d), #6d3e26); animation:memBackIn .65s ease-out; }
      .mem-card-mark { color:rgba(255,255,255,0.55); font-size:1.4rem; }
      .mem-card-face--front { transform:rotateY(180deg); background:var(--card,var(--paper)); border:2px solid var(--line,var(--border)); }
      .mem-card-face--front img { width:100%; height:100%; object-fit:cover; filter:blur(0); transition:filter .3s; }
      .mem-card--open .mem-card-face--front img { animation:memPhotoIn .7s ease-out; }
      @keyframes memBackIn { 0%{ filter:blur(8px); opacity:.3; } 100%{ filter:blur(0); opacity:1; } }
      @keyframes memPhotoIn { 0%{ filter:blur(13px); opacity:.2; } 100%{ filter:blur(0); opacity:1; } }
      .mem-card--selected .mem-card-face--back { box-shadow:0 0 0 3px var(--copper,#a5603d) inset; }
      .mem-card--correct .mem-card-face--front { border-color:#3a9552; box-shadow:0 0 0 3px #3a9552; }
      .mem-card--wrong .mem-card-face--front { border-color:#c0392b; box-shadow:0 0 0 3px #c0392b; }
      .mem-card--broken .mem-card-face--front { background:var(--line,var(--border)); }
      .mem-card--broken .mem-card-face--front::before { content:"\ud83e\udde9"; font-size:1.8rem; opacity:0.5; }
      .mem-card-caption { position:absolute; left:0; right:0; bottom:0; background:rgba(20,17,12,0.72); color:#fff; font-size:0.62rem; line-height:1.25; text-align:center; padding:0.25rem 0.2rem; }
      .mem-progress-wrap { height:5px; background:var(--line,var(--border)); border-radius:3px; overflow:hidden; max-width:420px; margin:0 auto 0.9rem; }
      .mem-progress-bar { height:100%; background:var(--copper,#a5603d); width:100%; transform-origin:left; animation:memShrink ${MEMORY_MEMORIZE_MS}ms linear forwards; }
      @keyframes memShrink { from{ transform:scaleX(1); } to{ transform:scaleX(0); } }
      .mem-hud { display:flex; justify-content:space-between; align-items:baseline; max-width:420px; margin:0 auto 0.6rem; font-size:0.85rem; color:var(--muted); }
      .mem-hud strong { color:var(--ink); }
      .mem-resolution { max-width:420px; margin:1rem auto 0; text-align:center; }
      .mem-resolution p { margin:0 0 0.9rem; font-size:0.95rem; }
      .mem-pair-reveal { background:var(--card,var(--paper)); border:1px solid var(--line,var(--border)); border-radius:10px; padding:0.7rem 1rem; margin:0 0 1rem; }
      .mem-pair-reveal-label { font-size:0.72rem; text-transform:uppercase; letter-spacing:0.05em; color:var(--muted); font-weight:600; margin:0 0 0.3rem; }
      .mem-pair-reveal p:last-child { margin:0; font-size:0.95rem; }
      .mem-explore-hint { font-size:0.78rem; color:var(--muted); text-align:center; margin:0.6rem 0 0; }
      .mem-btn { background:var(--copper,#a5603d); color:#fff; border:none; padding:0.75rem 2rem; border-radius:24px; font-size:0.95rem; font-family:inherit; cursor:pointer; font-weight:600; }
      .mem-level-picker { display:flex; flex-direction:column; gap:0.7rem; max-width:420px; margin:0 auto 1.6rem; }
      .mem-level-card { display:block; width:100%; text-align:left; background:var(--card,var(--paper)); border:1px solid var(--line,var(--border)); border-radius:12px; padding:0.9rem 1.1rem; cursor:pointer; font-family:inherit; }
      .mem-level-card:hover { border-color:var(--copper); }
      .mem-level-switcher { display:flex; align-items:center; justify-content:center; gap:0.4rem; max-width:420px; margin:0 auto 0.8rem; font-size:0.8rem; }
      .mem-level-switcher-label { color:var(--muted); margin-right:0.2rem; }
      .mem-level-pill { display:inline-flex; align-items:center; justify-content:center; min-width:1.8rem; padding:0.2rem 0.5rem; border-radius:99px; border:1.5px solid var(--line,var(--border)); color:var(--muted); text-decoration:none; font-weight:600; cursor:pointer; }
      .mem-level-pill:hover { border-color:var(--copper); color:var(--copper); }
      .mem-level-pill--active { background:var(--copper,#a5603d); border-color:var(--copper,#a5603d); color:#fff; cursor:default; }
      .mem-rule-box { background:color-mix(in srgb, var(--copper) 8%, var(--paper)); border:1px solid var(--copper); border-radius:12px; padding:1rem 1.2rem; margin:0 0 1.4rem; font-size:0.9rem; line-height:1.55; }
      .mem-rule-box-label { font-size:0.72rem; text-transform:uppercase; letter-spacing:0.05em; color:var(--copper); font-weight:700; margin:0 0 0.4rem; }
      .mem-level-card strong { display:block; font-size:1rem; color:var(--ink); margin-bottom:0.15rem; }
      .mem-level-card span { font-size:0.82rem; color:var(--muted); }
    </style>
  `;
}

function _memoryIntroScreen(level) {
  const meta = MEMORY_LEVEL_META[level];
  const best = _memoryGetBest(level);
  return shell(`
    <div class="page-container">
      ${pageHeader("wissen")}
      <div class="page-content">
        <p class="eyebrow">Wissen &middot; ${meta.label}</p>
        <h1 class="section-title">${meta.label}</h1>
        ${_memoryLevelSwitcher(level)}
        <p class="psycho-intro">Neun Portr\u00e4tfotos werden aufgedeckt &ndash; genau zwei davon bilden ein Paar. Merken Sie sich die Gesichter, nicht die Namen: Es geht rein um die Blickqualit\u00e4t. Nach ${MEMORY_MEMORIZE_MS / 1000} Sekunden werden die Karten verdeckt, und Sie m\u00fcssen aus dem Ged\u00e4chtnis das richtige Paar anklicken. 10 Runden pro Durchgang &ndash; nach jeder Runde d\u00fcrfen Sie zus\u00e4tzlich alle neun Karten antippen, um Name und Typ jeder Person zu sehen.</p>
        <div class="mem-rule-box">
          <p class="mem-rule-box-label">Was z\u00e4hlt in dieser Stufe als Paar?</p>
          <p style="margin:0;">${meta.rule}</p>
        </div>
        <div style="background:var(--card,var(--paper));border:1px solid var(--line,var(--border));border-left:4px solid var(--copper);border-radius:12px;padding:1rem 1.2rem;margin:0 0 1.6rem;font-size:.9rem;">
          Die Karten stammen aus allen \u00fcber ${Math.floor((BERUEHMT_PORTRAITS.length + KRIMINAL_PORTRAITS.length + KRANKHEITS_PORTRAITS.length) / 100) * 100} Portr\u00e4ts des Kompasses &ndash; Ber\u00fchmte Pers\u00f6nlichkeiten, Kriminalpsychologie und Krankheitsportr\u00e4ts gemischt. Je mehr Portr\u00e4ts hinzukommen, desto gr\u00f6\u00dfer wird der Kartenpool automatisch.
        </div>
        ${best > 0 ? `<p style="text-align:center;color:var(--muted);font-size:0.9rem;margin-bottom:1.2rem;">Ihre Bestleistung in dieser Stufe: <strong style="color:var(--ink);">${best}/${MEMORY_TOTAL_ROUNDS}</strong></p>` : ""}
        <div style="text-align:center;">
          <button class="mem-btn" onclick="window._memoryStart(${level})">Spiel starten &rarr;</button>
        </div>
      </div>
      ${_memoryStyles()}
    </div>
  `);
}

function _memoryGameScreen() {
  const st = _memoryState;
  const meta = MEMORY_LEVEL_META[st.level];
  const cardsHtml = st.cards.map((c, i) => _memoryCardHtml(c, i, st)).join("");
  const showProgress = st.phase === "memorize";
  let footer = "";
  if (st.phase === "memorize") {
    footer = `<p style="text-align:center;color:var(--muted);font-size:0.85rem;">Merken Sie sich die Gesichter &ndash; gleich werden die Karten verdeckt \u2026</p>`;
  } else if (st.phase === "guess") {
    footer = `<p style="text-align:center;color:var(--muted);font-size:0.85rem;">Klicken Sie die zwei Karten, die ein Paar bilden.</p>`;
  } else if (st.phase === "roundResult") {
    const msg = st.resolution.correct
      ? "Richtig erkannt!"
      : "Leider daneben &ndash; das eigentliche Paar ist gr\u00fcn markiert.";
    const isLast = st.round >= MEMORY_TOTAL_ROUNDS;
    const [pairA, pairB] = st.resolution.correctIdxs.map(i => st.cards[i]);
    const pairReveal = pairA && pairB ? `
      <div class="mem-pair-reveal">
        <p class="mem-pair-reveal-label">Das Paar &ndash; beide ${_memoryCardLabel(pairA.subtyp, st.level)}:</p>
        <p><strong>${pairA.name}</strong> &amp; <strong>${pairB.name}</strong></p>
      </div>
    ` : "";
    footer = `
      <div class="mem-resolution">
        <p><strong>${msg}</strong></p>
        ${pairReveal}
        <p class="mem-explore-hint">Tippen Sie auf die \u00fcbrigen Karten, um zu sehen, wer sie sind.</p>
        <button class="mem-btn" onclick="window._memoryNextRound()">${isLast ? "Endergebnis &rarr;" : "N\u00e4chste Runde &rarr;"}</button>
      </div>
    `;
  }
  return shell(`
    <div class="page-container">
      ${pageHeader("wissen")}
      <div class="page-content">
        <p class="eyebrow">Wissen &middot; ${meta.label}</p>
        <h1 class="section-title">${meta.label}</h1>
        ${_memoryLevelSwitcher(st.level)}
        <div class="mem-hud">
          <span>Runde <strong>${st.round}</strong> / ${MEMORY_TOTAL_ROUNDS}</span>
          <span>Punkte: <strong>${st.score}</strong></span>
        </div>
        ${showProgress ? `<div class="mem-progress-wrap"><div class="mem-progress-bar"></div></div>` : ""}
        <div class="mem-grid">${cardsHtml}</div>
        ${footer}
      </div>
      ${_memoryStyles()}
    </div>
  `);
}

function _memoryGameOverScreen() {
  const st = _memoryState;
  const meta = MEMORY_LEVEL_META[st.level];
  const best = _memoryGetBest(st.level);
  const pct = Math.round((st.score / MEMORY_TOTAL_ROUNDS) * 100);
  let msg;
  if (pct >= 90) msg = "Au\u00dfergew\u00f6hnlich &ndash; ein sehr geschulter Blick f\u00fcr Blickqualit\u00e4ten!";
  else if (pct >= 70) msg = "Sehr gut! Die Gesichter der Subtypen pr\u00e4gen sich bei Ihnen schon deutlich ein.";
  else if (pct >= 40) msg = "Solide Runde &ndash; mit mehr \u00dcbung wird der Blick noch sicherer.";
  else msg = "Ein Anfang &ndash; das Erkennen von Blickqualit\u00e4ten braucht \u00dcbung. Nochmal versuchen?";
  return shell(`
    <div class="page-container">
      ${pageHeader("wissen")}
      <div class="page-content" style="text-align:center;">
        <p class="eyebrow">Wissen &middot; ${meta.label}</p>
        <h1 class="section-title">${st.score} von ${MEMORY_TOTAL_ROUNDS} richtig</h1>
        ${_memoryLevelSwitcher(st.level)}
        <p style="color:var(--muted);margin:0 0 0.8rem;">${pct}&thinsp;%</p>
        <p style="max-width:420px;margin:0 auto 1rem;">${msg}</p>
        <p style="color:var(--muted);font-size:0.9rem;margin-bottom:2rem;">Bestleistung in dieser Stufe: <strong style="color:var(--ink);">${best}/${MEMORY_TOTAL_ROUNDS}</strong></p>
        <button class="mem-btn" onclick="window._memoryRestart()">Neue Runde &rarr;</button>
      </div>
      ${_memoryStyles()}
    </div>
  `);
}

function _enneagrammMemoryLevelPage(level) {
  if (!_memoryState || _memoryState.level !== level || _memoryState.phase === "loading") return _memoryIntroScreen(level);
  if (_memoryState.phase === "roundLoading") return _memoryRoundLoadingScreen();
  if (_memoryState.phase === "gameOver") return _memoryGameOverScreen();
  return _memoryGameScreen();
}

function enneagrammMemoryPage() {
  const level = _memoryState ? _memoryState.level : _memoryLastLevel;
  return _enneagrammMemoryLevelPage(level);
}

function _memoryRoundLoadingScreen() {
  const st = _memoryState;
  const meta = MEMORY_LEVEL_META[st.level];
  return shell(`
    <div class="page-container">
      ${pageHeader("wissen")}
      <div class="page-content" style="text-align:center;padding-top:3rem;padding-bottom:5rem;">
        <p class="eyebrow">Wissen &middot; ${meta.label}</p>
        <h1 class="section-title">${meta.label}</h1>
        <p style="color:var(--muted);margin-top:1.5rem;">Runde wird vorbereitet \u2026</p>
      </div>
    </div>
  `);
}

function enneagrammMemory1Page() { return _enneagrammMemoryLevelPage(1); }
function enneagrammMemory2Page() { return _enneagrammMemoryLevelPage(2); }
function enneagrammMemory3Page() { return _enneagrammMemoryLevelPage(3); }


// ---------------------------------------------------------------------------
// Enneagramm-Flashcards: Multiple-Choice-Trainer, Ableger von Enneagramm-Memory.
// Ein Portr\u00e4tfoto wird gezeigt, vier Antwortm\u00f6glichkeiten stehen zur Wahl \u2013
// nur eine ist richtig. Nutzt dieselbe Bildpool-/Validierungs-Infrastruktur
// und dieselben drei Granularit\u00e4tsstufen wie Enneagramm-Memory (Grundtyp /
// Grundtyp+Fl\u00fcgel / voller Subtyp), aber als reines Wiedererkennungstraining
// statt Paare-Finden. 10 Fragen pro Runde, Bestleistung je Stufe gespeichert.
// ---------------------------------------------------------------------------

const FLASH_TOTAL_ROUNDS = 10;
const FLASH_LEVEL_META = {
  1: { label: "Enneagramm-Flashcards I", sub: "Anf\u00e4nger \u00b7 nur der Grundtyp z\u00e4hlt",
       rule: "Sie sehen ein Portr\u00e4tfoto und vier Antwortm\u00f6glichkeiten, jede ein <strong>Grundtyp (1&ndash;9)</strong>. Gefragt ist nur der Grundtyp der Person &ndash; Instinktvariante und Fl\u00fcgel spielen keine Rolle." },
  2: { label: "Enneagramm-Flashcards II", sub: "Fortgeschrittene \u00b7 Grundtyp + Fl\u00fcgel",
       rule: "Sie sehen ein Portr\u00e4tfoto und vier Antwortm\u00f6glichkeiten, jede eine Kombination aus <strong>Grundtyp + Fl\u00fcgel</strong> (z. B. 4w3). Gefragt ist Typ und Fl\u00fcgel &ndash; die Instinktvariante (SE/SO/SX) spielt keine Rolle." },
  3: { label: "Enneagramm-Flashcards III", sub: "Experten \u00b7 vollst\u00e4ndiger Subtyp (Instinkt+Typ+Fl\u00fcgel)",
       rule: "Sie sehen ein Portr\u00e4tfoto und vier Antwortm\u00f6glichkeiten, jede ein <strong>vollst\u00e4ndiger Subtyp</strong> (z. B. SO1w9). Gefragt ist die exakte Kombination aus Instinktvariante, Typ und Fl\u00fcgel." },
};

let _flashState = null;
let _flashLastLevel = 1;

function _flashBestKey(level) { return "kompass:flashBest:" + level; }
function _flashSaveBest(level, score) {
  try {
    const prev = parseInt(localStorage.getItem(_flashBestKey(level)) || "0", 10);
    if (score > prev) localStorage.setItem(_flashBestKey(level), String(score));
  } catch (e) {}
}
function _flashGetBest(level) {
  try { return parseInt(localStorage.getItem(_flashBestKey(level)) || "0", 10); } catch (e) { return 0; }
}

function _flashRerender() {
  if (location.hash === "#enneagramm-flashcards") { render(); } else { location.hash = "enneagramm-flashcards"; }
}

async function _flashPickQuestion(level) {
  const pools = _memoryBuildPools(level);
  const keys = _memoryShuffle(Object.keys(pools));
  for (const correctKey of keys) {
    const found = await _memoryFindValidPortrait(_memoryShuffle(pools[correctKey]), new Set());
    if (!found) continue;
    const otherKeys = _memoryShuffle(Object.keys(pools).filter(k => k !== correctKey)).slice(0, 3);
    if (otherKeys.length < 3) continue;
    const options = _memoryShuffle([correctKey, ...otherKeys]);
    return { portrait: found, correctKey, options };
  }
  return null;
}

async function _flashNextRound() {
  const st = _flashState;
  if (!st) return;
  st.round += 1;
  if (st.round > FLASH_TOTAL_ROUNDS) {
    st.phase = "gameOver";
    _flashSaveBest(st.level, st.score);
    _flashRerender();
    return;
  }
  st.phase = "loading";
  _flashRerender();
  const q = await _flashPickQuestion(st.level);
  if (_flashState !== st) return;
  if (!q) { st.phase = "gameOver"; _flashRerender(); return; }
  st.question = q;
  st.answered = false;
  st.selectedKey = null;
  st.phase = "question";
  _flashRerender();
}

window._flashStart = function (level) {
  const lvl = FLASH_LEVEL_META[level] ? level : 1;
  _flashLastLevel = lvl;
  _flashState = { level: lvl, phase: "loading", round: 0, score: 0, question: null, answered: false, selectedKey: null };
  _flashNextRound();
};

window._flashSwitchLevel = function (level) {
  const lvl = FLASH_LEVEL_META[level] ? level : 1;
  _flashLastLevel = lvl;
  _flashState = null;
  _flashRerender();
};

window._flashAnswer = function (key) {
  const st = _flashState;
  if (!st || st.phase !== "question" || st.answered) return;
  st.answered = true;
  st.selectedKey = key;
  if (key === st.question.correctKey) st.score += 1;
  _flashRerender();
};

window._flashNextRound = function () { _flashNextRound(); };
window._flashRestart = function () {
  const lvl = _flashState ? _flashState.level : 1;
  window._flashStart(lvl);
};

function _flashLevelSwitcher(currentLevel) {
  const items = [1,2,3].map(l => {
    const active = l === currentLevel;
    return active
      ? `<span class="mem-level-pill mem-level-pill--active">${l===1?"I":l===2?"II":"III"}</span>`
      : `<a href="javascript:void(0)" class="mem-level-pill" onclick="window._flashSwitchLevel(${l})">${l===1?"I":l===2?"II":"III"}</a>`;
  }).join("");
  return `<div class="mem-level-switcher"><span class="mem-level-switcher-label">Stufe:</span>${items}</div>`;
}

function _flashStyles() {
  return `
    <style>
      .mem-level-switcher { display:flex; align-items:center; justify-content:center; gap:0.4rem; max-width:420px; margin:0 auto 0.8rem; font-size:0.8rem; }
      .mem-level-switcher-label { color:var(--muted); margin-right:0.2rem; }
      .mem-level-pill { display:inline-flex; align-items:center; justify-content:center; min-width:1.8rem; padding:0.2rem 0.5rem; border-radius:99px; border:1.5px solid var(--line,var(--border)); color:var(--muted); text-decoration:none; font-weight:600; cursor:pointer; }
      .mem-level-pill:hover { border-color:var(--copper); color:var(--copper); }
      .mem-level-pill--active { background:var(--copper,#a5603d); border-color:var(--copper,#a5603d); color:#fff; cursor:default; }
      .flash-rule-box { background:color-mix(in srgb, var(--copper) 8%, var(--paper)); border:1px solid var(--copper); border-radius:12px; padding:1rem 1.2rem; margin:0 0 1.4rem; font-size:0.9rem; line-height:1.55; }
      .flash-rule-box-label { font-size:0.72rem; text-transform:uppercase; letter-spacing:0.05em; color:var(--copper); font-weight:700; margin:0 0 0.4rem; }
      .flash-photo-wrap { max-width:320px; margin:1.2rem auto; border-radius:14px; overflow:hidden; border:1px solid var(--line,var(--border)); aspect-ratio:1/1; }
      .flash-photo-wrap img { width:100%; height:100%; object-fit:cover; display:block; animation:flashPhotoIn .6s ease-out; }
      @keyframes flashPhotoIn { 0%{ filter:blur(13px); opacity:.2; } 100%{ filter:blur(0); opacity:1; } }
      .flash-options { display:grid; grid-template-columns:1fr 1fr; gap:0.7rem; max-width:420px; margin:1.2rem auto 0; }
      .flash-opt { padding:0.85rem 0.6rem; border-radius:10px; border:2px solid var(--line,var(--border)); background:var(--card,var(--paper)); font-size:0.95rem; font-weight:600; cursor:pointer; font-family:inherit; color:var(--ink); text-align:center; }
      .flash-opt:hover { border-color:var(--copper); }
      .flash-opt--correct { border-color:#3a9552; background:color-mix(in srgb, #3a9552 14%, var(--paper)); color:#3a9552; }
      .flash-opt--wrong { border-color:#c0392b; background:color-mix(in srgb, #c0392b 14%, var(--paper)); color:#c0392b; }
      .flash-opt[disabled] { cursor:default; }
      .flash-hud { display:flex; justify-content:space-between; align-items:baseline; max-width:420px; margin:0 auto 0.6rem; font-size:0.85rem; color:var(--muted); }
      .flash-hud strong { color:var(--ink); }
      .flash-feedback { text-align:center; max-width:420px; margin:1.2rem auto 0; }
      .flash-feedback p { margin:0 0 0.9rem; font-size:0.95rem; }
      .flash-name-reveal { background:var(--card,var(--paper)); border:1px solid var(--line,var(--border)); border-radius:10px; padding:0.7rem 1rem; margin:0 0 1rem; font-size:0.92rem; }
      .flash-btn { background:var(--copper,#a5603d); color:#fff; border:none; padding:0.75rem 2rem; border-radius:24px; font-size:0.95rem; font-family:inherit; cursor:pointer; font-weight:600; }
      .flash-explore-hint { font-size:0.78rem; color:var(--muted); text-align:center; margin:0.6rem 0 0; }
    </style>
  `;
}

function _flashIntroScreen(level) {
  const meta = FLASH_LEVEL_META[level];
  const best = _flashGetBest(level);
  return shell(`
    <div class="page-container">
      ${pageHeader("wissen")}
      <div class="page-content">
        <p class="eyebrow">Wissen &middot; ${meta.label}</p>
        <h1 class="section-title">${meta.label}</h1>
        ${_flashLevelSwitcher(level)}
        <p class="psycho-intro">Ein Portr\u00e4tfoto, vier Antwortm\u00f6glichkeiten &ndash; sofortiges Feedback, 10 Fragen pro Runde. Anders als beim Memory geht es hier ums schnelle Wiedererkennen, nicht ums Merken von Positionen.</p>
        <div class="flash-rule-box">
          <p class="flash-rule-box-label">Wonach wird in dieser Stufe gefragt?</p>
          <p style="margin:0;">${meta.rule}</p>
        </div>
        ${best > 0 ? `<p style="text-align:center;color:var(--muted);font-size:0.9rem;margin-bottom:1.2rem;">Ihre Bestleistung in dieser Stufe: <strong style="color:var(--ink);">${best}/${FLASH_TOTAL_ROUNDS}</strong></p>` : ""}
        <div style="text-align:center;">
          <button class="flash-btn" onclick="window._flashStart(${level})">Quiz starten &rarr;</button>
        </div>
      </div>
      ${_flashStyles()}
    </div>
  `);
}

function _flashLoadingScreen() {
  const st = _flashState;
  const meta = FLASH_LEVEL_META[st.level];
  return shell(`
    <div class="page-container">
      ${pageHeader("wissen")}
      <div class="page-content" style="text-align:center;padding-top:3rem;padding-bottom:5rem;">
        <p class="eyebrow">Wissen &middot; ${meta.label}</p>
        <h1 class="section-title">${meta.label}</h1>
        <p style="color:var(--muted);margin-top:1.5rem;">Frage wird vorbereitet \u2026</p>
      </div>
    </div>
  `);
}

function _flashQuestionScreen() {
  const st = _flashState;
  const meta = FLASH_LEVEL_META[st.level];
  const q = st.question;
  const optionsHtml = q.options.map(key => {
    const display = _flashKeyLabel(key, st.level);
    let cls = "flash-opt";
    let disabled = st.answered ? "disabled" : "";
    if (st.answered) {
      if (key === q.correctKey) cls += " flash-opt--correct";
      else if (key === st.selectedKey) cls += " flash-opt--wrong";
    }
    const onclick = st.answered ? "" : ` onclick="window._flashAnswer('${key}')"`;
    return `<button class="${cls}" ${disabled}${onclick}>${display}</button>`;
  }).join("");

  let feedback = "";
  if (st.answered) {
    const correct = st.selectedKey === q.correctKey;
    const isLast = st.round >= FLASH_TOTAL_ROUNDS;
    feedback = `
      <div class="flash-feedback">
        <p><strong>${correct ? "Richtig!" : "Leider falsch."}</strong></p>
        <div class="flash-name-reveal">${q.portrait.name} &ndash; <strong>${(q.portrait.subtyp||"").toUpperCase()}</strong></div>
        <button class="flash-btn" onclick="window._flashNextRound()">${isLast ? "Endergebnis &rarr;" : "N\u00e4chste Frage &rarr;"}</button>
      </div>
    `;
  }

  return shell(`
    <div class="page-container">
      ${pageHeader("wissen")}
      <div class="page-content">
        <p class="eyebrow">Wissen &middot; ${meta.label}</p>
        <h1 class="section-title">${meta.label}</h1>
        ${_flashLevelSwitcher(st.level)}
        <div class="flash-hud">
          <span>Frage <strong>${st.round}</strong> / ${FLASH_TOTAL_ROUNDS}</span>
          <span>Punkte: <strong>${st.score}</strong></span>
        </div>
        <div class="flash-photo-wrap"><img src="${q.portrait.img}" alt="" /></div>
        <p style="text-align:center;color:var(--muted);font-size:0.85rem;">${st.level === 1 ? "Welcher Grundtyp ist das?" : st.level === 2 ? "Welcher Grundtyp + Fl\u00fcgel ist das?" : "Welcher Subtyp ist das?"}</p>
        <div class="flash-options">${optionsHtml}</div>
        ${feedback}
      </div>
      ${_flashStyles()}
    </div>
  `);
}

function _flashKeyLabel(key, level) {
  if (level === 1) return "Typ " + key.slice(1);
  if (level === 2) { const m = key.match(/^T(\d)W(\d)$/); return m ? (m[1] + "w" + m[2]) : key; }
  const m = key.match(/^(SE|SO|SX)(\d)W?(\d)?$/);
  return m ? (m[1] + m[2] + (m[3] ? "w" + m[3] : "")) : key;
}

function _flashGameOverScreen() {
  const st = _flashState;
  const meta = FLASH_LEVEL_META[st.level];
  const best = _flashGetBest(st.level);
  const pct = Math.round((st.score / FLASH_TOTAL_ROUNDS) * 100);
  let msg;
  if (pct >= 90) msg = "Au\u00dfergew\u00f6hnlich &ndash; ein sehr geschulter Blick f\u00fcr Blickqualit\u00e4ten!";
  else if (pct >= 70) msg = "Sehr gut! Die Gesichter der Subtypen pr\u00e4gen sich bei Ihnen schon deutlich ein.";
  else if (pct >= 40) msg = "Solide Runde &ndash; mit mehr \u00dcbung wird der Blick noch sicherer.";
  else msg = "Ein Anfang &ndash; das Erkennen von Blickqualit\u00e4ten braucht \u00dcbung. Nochmal versuchen?";
  return shell(`
    <div class="page-container">
      ${pageHeader("wissen")}
      <div class="page-content" style="text-align:center;">
        <p class="eyebrow">Wissen &middot; ${meta.label}</p>
        <h1 class="section-title">${st.score} von ${FLASH_TOTAL_ROUNDS} richtig</h1>
        ${_flashLevelSwitcher(st.level)}
        <p style="color:var(--muted);margin:0 0 0.8rem;">${pct}&thinsp;%</p>
        <p style="max-width:420px;margin:0 auto 1rem;">${msg}</p>
        <p style="color:var(--muted);font-size:0.9rem;margin-bottom:2rem;">Bestleistung in dieser Stufe: <strong style="color:var(--ink);">${best}/${FLASH_TOTAL_ROUNDS}</strong></p>
        <button class="flash-btn" onclick="window._flashRestart()">Neue Runde &rarr;</button>
      </div>
      ${_flashStyles()}
    </div>
  `);
}

function enneagrammFlashcardsPage() {
  if (!_flashState) return _flashIntroScreen(_flashLastLevel);
  if (_flashState.phase === "loading") return _flashLoadingScreen();
  if (_flashState.phase === "gameOver") return _flashGameOverScreen();
  return _flashQuestionScreen();
}

// ---------------------------------------------------------------------------
// Comicfiguren-Quiz: Multiple-Choice-Ratespiel mit den 27 Subtyp-Karikaturen
// (Illustrationen: Tessa Fabritz). Zwei Stufen: Grundtyp (1\u20139) oder voller
// Subtyp (SE1\u2026SX9). Wiederverwendet die visuelle Sprache der Flashcards.
// ---------------------------------------------------------------------------

const CQUIZ_TOTAL_ROUNDS = 10;
const CQUIZ_LEVEL_META = {
  1: { label: "Comicfiguren-Quiz I", sub: "Anf\u00e4nger \u00b7 nur der Grundtyp z\u00e4hlt",
       rule: "Sie sehen eine Subtyp-Karikatur und vier Antwortm\u00f6glichkeiten, jede ein <strong>Grundtyp (1&ndash;9)</strong>. Gefragt ist nur der Grundtyp &ndash; die Instinktvariante (SE/SO/SX) spielt keine Rolle." },
  2: { label: "Comicfiguren-Quiz II", sub: "Experten \u00b7 voller Subtyp (Instinkt+Typ)",
       rule: "Sie sehen eine Subtyp-Karikatur und vier Antwortm\u00f6glichkeiten, jede ein <strong>voller Subtyp</strong> (z. B. SO4). Gefragt ist die exakte Kombination aus Instinktvariante und Typ." },
};

let _cquizState = null;
let _cquizLastLevel = 1;

function _cquizBestKey(level) { return "kompass:cquizBest:" + level; }
function _cquizSaveBest(level, score) {
  try {
    const prev = parseInt(localStorage.getItem(_cquizBestKey(level)) || "0", 10);
    if (score > prev) localStorage.setItem(_cquizBestKey(level), String(score));
  } catch (e) {}
}
function _cquizGetBest(level) {
  try { return parseInt(localStorage.getItem(_cquizBestKey(level)) || "0", 10); } catch (e) { return 0; }
}
function _cquizRerender() {
  if (location.hash === "#subtyp-comicquiz") { render(); } else { location.hash = "subtyp-comicquiz"; }
}
function _cquizShuffle(arr) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; }
  return a;
}

function _cquizPickQuestion(level, usedCodes) {
  const pool = SUBTYP_COMIC.filter(s => !usedCodes.has(s.code));
  const source = pool.length ? pool : SUBTYP_COMIC;
  const item = _cquizShuffle(source)[0];
  const correctKey = level === 1 ? item.code.slice(2) : item.code;
  let distractPool;
  if (level === 1) {
    distractPool = ["1","2","3","4","5","6","7","8","9"].filter(n => n !== correctKey);
  } else {
    distractPool = SUBTYP_COMIC.map(s => s.code).filter(c => c !== correctKey);
  }
  const distractors = _cquizShuffle(distractPool).slice(0, 3);
  const options = _cquizShuffle([correctKey, ...distractors]);
  return { item, correctKey, options };
}

function _cquizNextRound() {
  const st = _cquizState;
  if (!st) return;
  st.round += 1;
  if (st.round > CQUIZ_TOTAL_ROUNDS) {
    st.phase = "gameOver";
    _cquizSaveBest(st.level, st.score);
    _cquizRerender();
    return;
  }
  const q = _cquizPickQuestion(st.level, st.usedCodes);
  st.usedCodes.add(q.item.code);
  st.question = q;
  st.answered = false;
  st.selectedKey = null;
  st.phase = "question";
  _cquizRerender();
}

window._cquizStart = function (level) {
  const lvl = CQUIZ_LEVEL_META[level] ? level : 1;
  _cquizLastLevel = lvl;
  _cquizState = { level: lvl, phase: "question", round: 0, score: 0, question: null, answered: false, selectedKey: null, usedCodes: new Set() };
  _cquizNextRound();
};
window._cquizSwitchLevel = function (level) {
  const lvl = CQUIZ_LEVEL_META[level] ? level : 1;
  _cquizLastLevel = lvl;
  _cquizState = null;
  _cquizRerender();
};
window._cquizAnswer = function (key) {
  const st = _cquizState;
  if (!st || st.phase !== "question" || st.answered) return;
  st.answered = true;
  st.selectedKey = key;
  if (key === st.question.correctKey) st.score += 1;
  _cquizRerender();
};
window._cquizNextRound = function () { _cquizNextRound(); };
window._cquizRestart = function () {
  const lvl = _cquizState ? _cquizState.level : 1;
  window._cquizStart(lvl);
};

function _cquizLevelSwitcher(currentLevel) {
  const items = [1,2].map(l => {
    const active = l === currentLevel;
    return active
      ? `<span class="mem-level-pill mem-level-pill--active">${l===1?"I":"II"}</span>`
      : `<a href="javascript:void(0)" class="mem-level-pill" onclick="window._cquizSwitchLevel(${l})">${l===1?"I":"II"}</a>`;
  }).join("");
  return `<div class="mem-level-switcher"><span class="mem-level-switcher-label">Stufe:</span>${items}</div>`;
}

function _cquizKeyLabel(key, level) {
  return level === 1 ? "Typ " + key : key;
}

function _cquizIntroScreen(level) {
  const meta = CQUIZ_LEVEL_META[level];
  const best = _cquizGetBest(level);
  return shell(`
    <div class="page-container">
      ${pageHeader("wissen")}
      <div class="page-content">
        <p class="eyebrow">Wissen &middot; ${meta.label}</p>
        <h1 class="section-title">${meta.label}</h1>
        ${_cquizLevelSwitcher(level)}
        <p class="psycho-intro">Eine Subtyp-Karikatur, vier Antwortm\u00f6glichkeiten &ndash; sofortiges Feedback, 10 Fragen pro Runde. Illustrationen: Tessa Fabritz.</p>
        <div class="flash-rule-box">
          <p class="flash-rule-box-label">Wonach wird in dieser Stufe gefragt?</p>
          <p style="margin:0;">${meta.rule}</p>
        </div>
        ${best > 0 ? `<p style="text-align:center;color:var(--muted);font-size:0.9rem;margin-bottom:1.2rem;">Ihre Bestleistung in dieser Stufe: <strong style="color:var(--ink);">${best}/${CQUIZ_TOTAL_ROUNDS}</strong></p>` : ""}
        <div style="text-align:center;">
          <button class="flash-btn" onclick="window._cquizStart(${level})">Quiz starten &rarr;</button>
        </div>
      </div>
      ${_flashStyles()}
    </div>
  `);
}

function _cquizQuestionScreen() {
  const st = _cquizState;
  const meta = CQUIZ_LEVEL_META[st.level];
  const q = st.question;
  const optionsHtml = q.options.map(key => {
    const display = _cquizKeyLabel(key, st.level);
    let cls = "flash-opt";
    let disabled = st.answered ? "disabled" : "";
    if (st.answered) {
      if (key === q.correctKey) cls += " flash-opt--correct";
      else if (key === st.selectedKey) cls += " flash-opt--wrong";
    }
    const onclick = st.answered ? "" : ` onclick="window._cquizAnswer('${key}')"`;
    return `<button class="${cls}" ${disabled}${onclick}>${display}</button>`;
  }).join("");

  let feedback = "";
  if (st.answered) {
    const correct = st.selectedKey === q.correctKey;
    const isLast = st.round >= CQUIZ_TOTAL_ROUNDS;
    feedback = `
      <div class="flash-feedback">
        <p><strong>${correct ? "Richtig!" : "Leider falsch."}</strong></p>
        <div class="flash-name-reveal">${q.item.label} (${q.item.code})<br><span style="color:var(--muted);font-size:0.85rem;">${q.item.text}</span></div>
        <button class="flash-btn" onclick="window._cquizNextRound()">${isLast ? "Endergebnis &rarr;" : "N\u00e4chste Frage &rarr;"}</button>
      </div>
    `;
  }

  return shell(`
    <div class="page-container">
      ${pageHeader("wissen")}
      <div class="page-content">
        <p class="eyebrow">Wissen &middot; ${meta.label}</p>
        <h1 class="section-title">${meta.label}</h1>
        ${_cquizLevelSwitcher(st.level)}
        <div class="flash-hud">
          <span>Frage <strong>${st.round}</strong> / ${CQUIZ_TOTAL_ROUNDS}</span>
          <span>Punkte: <strong>${st.score}</strong></span>
        </div>
        <div class="flash-photo-wrap" style="aspect-ratio:3/4;"><img src="https://pub-2851309644cc48aea2a2ae780b41b196.r2.dev/assets/subtyp-comic/${q.item.code.toLowerCase()}.jpg" alt="" /></div>
        <p style="text-align:center;color:var(--muted);font-size:0.85rem;">${st.level === 1 ? "Welcher Grundtyp ist das?" : "Welcher Subtyp ist das?"}</p>
        <div class="flash-options">${optionsHtml}</div>
        ${feedback}
      </div>
      ${_flashStyles()}
    </div>
  `);
}

function _cquizGameOverScreen() {
  const st = _cquizState;
  const meta = CQUIZ_LEVEL_META[st.level];
  const best = _cquizGetBest(st.level);
  const pct = Math.round((st.score / CQUIZ_TOTAL_ROUNDS) * 100);
  let msg;
  if (pct >= 90) msg = st.level === 1 ? "Au\u00dfergew\u00f6hnlich &ndash; Sie erkennen die neun Typen auf einen Blick!" : "Au\u00dfergew\u00f6hnlich &ndash; Sie erkennen die 27 Subtypen auf einen Blick!";
  else if (pct >= 70) msg = "Sehr gut! Die Karikaturen pr\u00e4gen sich bei Ihnen schon deutlich ein.";
  else if (pct >= 40) msg = "Solide Runde &ndash; mit mehr \u00dcbung wird der Blick noch sicherer.";
  else msg = "Ein Anfang &ndash; das Zuordnen braucht \u00dcbung. Nochmal versuchen?";
  return shell(`
    <div class="page-container">
      ${pageHeader("wissen")}
      <div class="page-content" style="text-align:center;">
        <p class="eyebrow">Wissen &middot; ${meta.label}</p>
        <h1 class="section-title">${st.score} von ${CQUIZ_TOTAL_ROUNDS} richtig</h1>
        ${_cquizLevelSwitcher(st.level)}
        <p style="color:var(--muted);margin:0 0 0.8rem;">${pct}&thinsp;%</p>
        <p style="max-width:420px;margin:0 auto 1rem;">${msg}</p>
        <p style="color:var(--muted);font-size:0.9rem;margin-bottom:2rem;">Bestleistung in dieser Stufe: <strong style="color:var(--ink);">${best}/${CQUIZ_TOTAL_ROUNDS}</strong></p>
        <button class="flash-btn" onclick="window._cquizRestart()">Neue Runde &rarr;</button>
      </div>
      ${_flashStyles()}
    </div>
  `);
}

function subtypComicQuizPage() {
  if (!_cquizState) return _cquizIntroScreen(_cquizLastLevel);
  if (_cquizState.phase === "gameOver") return _cquizGameOverScreen();
  return _cquizQuestionScreen();
}

// \u2500\u2500\u2500\u2500\u2500 Subtyp-Motivationsquiz \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
// Multiple-Choice-Ratespiel: Statt eines Fotos wird ausschlie\u00dflich motivationsbedingtes
// Verhalten beschrieben (die Leidenschaft/Fixierung des jeweiligen Subtyps in einer
// konkreten Alltagsszene) \u2013 bewusst subtil formuliert, ohne Instinkt- oder Typkennung im
// Text, damit die Aufgabe auch f\u00fcr subtypkundige Leser:innen fordernd bleibt.
const SUBTYP_MOTIVATION = [
  { code:"SE1", text:"Wenn im Haushalt etwas kaputtgeht, repariert er es am liebsten selbst und sofort, statt jemanden zu bitten \u2013 eigene Unordnung im direkten Lebensumfeld bereitet ihm ein schlechtes Gewissen. \u00c4rger \u00fcber andere zeigt er selten offen, sondern in einem angespannten, kontrollierten Tonfall, w\u00e4hrend er insgeheim genau registriert, wer sich nicht an Absprachen h\u00e4lt." },
  { code:"SO1", text:"Bei einer Vereinssitzung meldet er sich zu Wort, sobald ein Beschluss von der eigentlichen Satzung abweicht \u2013 nicht aus Profilierungssucht, sondern aus Mitverantwortung f\u00fcr die korrekte Ordnung der Gemeinschaft. Fehler anderer benennt er sachlich, aber unnachgiebig, mit dem stillen Anspruch, selbst \u00fcber jeden Vorwurf erhaben zu sein." },
  { code:"SX1", text:"Wenn der Partner eine Zusage nicht einh\u00e4lt, reagiert sie nicht mit offenem Vorwurf, sondern mit intensiver, kaum verhohlener Entt\u00e4uschung, die noch tagelang nachwirkt. Sie strebt danach, in der engsten Beziehung gemeinsam mit dem anderen die eine, vollkommene Verbindung zu verwirklichen, an der es nichts mehr zu korrigieren gibt." },
  { code:"SE2", text:"Statt Hilfe anzubieten, wartet er eher ab, bis jemand von sich aus fragt, wie es ihm geht \u2013 insgeheim hofft er, dass die F\u00fcrsorge f\u00fcr ihn selbst irgendwann genauso gro\u00df ausf\u00e4llt wie die, die er st\u00e4ndig f\u00fcr andere bereith\u00e4lt. Kleine, konkrete Gesten der Zuwendung bedeuten ihm mehr als gro\u00dfe Worte." },
  { code:"SO2", text:"In einer Gruppe \u00fcbernimmt er wie selbstverst\u00e4ndlich die Rolle, ohne die nichts richtig laufen w\u00fcrde, und misst seinen eigenen Wert genau daran, wie unentbehrlich er der Gemeinschaft gerade erscheint. Wird er einmal nicht gebraucht, empfindet er das rasch als Zur\u00fcckweisung, auch wenn objektiv nichts geschehen ist." },
  { code:"SX2", text:"Sie richtet ihre ganze Aufmerksamkeit auf eine einzige Person im Raum und spiegelt genau das zur\u00fcck, was der andere gerade zu brauchen scheint \u2013 nicht aus Berechnung, sondern weil exklusive N\u00e4he f\u00fcr sie der eigentliche Lebenssinn ist. Bleibt diese Intensit\u00e4t unerwidert, kippt die anf\u00e4ngliche Hingabe rasch in Eifersucht oder ein Gef\u00fchl tiefer Zur\u00fcckweisung." },
  { code:"SE3", text:"Auf die Frage nach dem eigenen Erfolg reagiert er eher zur\u00fcckhaltend und verweist lieber auf das, was konkret erledigt wurde, als auf ein gr\u00f6\u00dferes Ziel oder Image. Innerlich sichert er seinen Selbstwert nicht \u00fcber Applaus, sondern \u00fcber das stille Gef\u00fchl, verl\u00e4sslich zu funktionieren und gebraucht zu werden." },
  { code:"SO3", text:"Beim Betreten eines Raums scannt er in Sekundenbruchteilen, wer dort Einfluss hat, und passt Auftreten und Tonfall unbewusst genau an diese Erwartung an. Sein eigentlicher Antrieb ist die tiefe \u00dcberzeugung, dass sichtbarer Erfolg der einzige verl\u00e4ssliche Beweis f\u00fcr den eigenen Wert ist." },
  { code:"SX3", text:"In einem Gespr\u00e4ch zu zweit setzt er unauff\u00e4llig, aber gezielt Signale von Attraktivit\u00e4t und Kompetenz zugleich ein, sobald er merkt, dass jemand ihn wirklich wahrnimmt. Worum es ihm tief innen geht, ist nicht Ruhm vor vielen, sondern die Best\u00e4tigung, im Blick einer einzigen wichtigen Person unwiderstehlich zu sein." },
  { code:"SE4", text:"Auch wenn innerlich viel in ihr vorgeht, funktioniert sie in Krisen meist bemerkenswert diszipliniert weiter, w\u00e4hrend die eigentliche Sehnsucht nach einem authentischeren Leben nach au\u00dfen kaum sichtbar wird. Ihr Leiden zeigt sich seltener in Worten als in einer z\u00e4hen, fast unauff\u00e4lligen Standhaftigkeit." },
  { code:"SO4", text:"In einer Gruppe f\u00fchlt sie sich oft wie die Einzige, die wirklich versteht, wie kompliziert die eigene innere Welt ist, und vergleicht sich unwillk\u00fcrlich mit anderen, ohne dass daraus je echte Zugeh\u00f6rigkeit entsteht. Sichtbar gezeigtes Leiden ist f\u00fcr sie fast der einzige Beweis, wirklich besonders und einzigartig zu sein." },
  { code:"SX4", text:"Bekommt sie in einer Beziehung nicht die erhoffte Intensit\u00e4t zur\u00fcck, reagiert sie selten resigniert, sondern mit einer direkten, fast konfrontativen Forderung nach mehr echter N\u00e4he. Sie konkurriert unbewusst mit jedem, der ihr die besondere Verbindung streitig machen k\u00f6nnte, statt sich in stille Sehnsucht zur\u00fcckzuziehen." },
  { code:"SE5", text:"Bevor er sich auf ein Gespr\u00e4ch oder einen Termin einl\u00e4sst, sorgt er innerlich daf\u00fcr, dass genug R\u00fcckzugsraum und Zeit f\u00fcr sich selbst gesichert bleibt, notfalls durch feste, fast rituelle Routinen. Seine gr\u00f6\u00dfte Sorge ist nicht Einsamkeit, sondern dass die eigenen, begrenzten Kr\u00e4fte von au\u00dfen beansprucht werden k\u00f6nnten." },
  { code:"SO5", text:"In einer Fachdiskussion bringt er sein Wissen bereitwillig ein, sobald er merkt, dass es tats\u00e4chlich gebraucht wird \u2013 intellektueller Beitrag ist f\u00fcr ihn die eigentliche Form, zu einer Gruppe dazuzugeh\u00f6ren. Direkten emotionalen Austausch ersetzt er dabei oft unbemerkt durch das Teilen von Konzepten und Ideen." },
  { code:"SX5", text:"Nach au\u00dfen wirkt sie zur\u00fcckhaltend und schwer zug\u00e4nglich, doch sobald sich echtes Vertrauen zu einer einzigen Person aufbaut, \u00f6ffnet sie sich \u00fcberraschend intensiv und pers\u00f6nlich. Ihr eigentliches Ziel ist nicht Distanz, sondern die eine tiefe, exklusive Verbindung, in der sie sich ganz zeigen kann." },
  { code:"SE6", text:"Sie sucht sich gezielt ein kleines, verl\u00e4ssliches Netzwerk aus Menschen, denen sie vertraut, und h\u00e4lt daran auch dann fest, wenn objektiv bessere Optionen vorhanden w\u00e4ren. Sicherheit entsteht f\u00fcr sie vor allem durch Zugeh\u00f6rigkeit zu etwas Warmem und Verl\u00e4sslichem, nicht durch eigene St\u00e4rke." },
  { code:"SO6", text:"Bei wichtigen Entscheidungen orientiert er sich lieber an einer anerkannten Regel, einer Institution oder einer klaren Autorit\u00e4t, als sich allein auf das eigene Urteil zu verlassen. Seine Loyalit\u00e4t gilt weniger einzelnen Personen als dem System oder der Idee, der er dient \u2013 Zweifel daran f\u00fchlen sich bedrohlicher an als pers\u00f6nliche Kritik." },
  { code:"SX6", text:"Wo andere vor einer Konfrontation zur\u00fcckschrecken, sucht er sie eher aktiv \u2013 nicht aus Tollk\u00fchnheit, sondern um sich selbst zu beweisen, dass die eigene Angst ihn nicht beherrscht. Beziehungen testet er unbewusst h\u00e4ufig auf Belastbarkeit, bevor er sich wirklich sicher genug f\u00fchlt, um Vertrauen zuzulassen." },
  { code:"SE7", text:"Vor einer Reise oder einem gr\u00f6\u00dferen Vorhaben sorgt er zuverl\u00e4ssig daf\u00fcr, dass praktisch nichts fehlt \u2013 Vorr\u00e4te, Kontakte, ein Plan B \u2013, und genie\u00dft diese F\u00fclle sichtbar und konkret. Seine Angst vor Mangel zeigt sich weniger in Worten als in einem beinahe automatischen Bed\u00fcrfnis, sich immer gut abgesichert zu f\u00fchlen." },
  { code:"SO7", text:"Statt pers\u00f6nlichen Genuss offen auszuleben, stellt sie ihre Begeisterung lieber in den Dienst eines gemeinsamen Projekts oder einer Vision, der andere sich anschlie\u00dfen k\u00f6nnen. Ihr Enthusiasmus wirkt dadurch idealistischer und weniger selbstbezogen, als m\u00fcsste die eigene Freude erst durch einen h\u00f6heren Zweck gerechtfertigt werden." },
  { code:"SX7", text:"Er l\u00e4sst sich schnell und aufrichtig von einer neuen Idee, einem Menschen oder einem Erlebnis begeistern \u2013 fast idealisierend \u2013 und \u00fcbertr\u00e4gt diese Faszination sp\u00fcrbar auf andere in seiner N\u00e4he. Verliert die Sache ihren Reiz, wendet er sich mit derselben Intensit\u00e4t dem n\u00e4chsten Vorhaben zu, ohne lange zur\u00fcckzublicken." },
  { code:"SE8", text:"Bevor er sich auf andere verl\u00e4sst, sorgt er selbst daf\u00fcr, dass die eigenen Grundbed\u00fcrfnisse gedeckt sind, notfalls im Alleingang und ohne lange zu fragen. Von Autorit\u00e4ten l\u00e4sst er sich ungern etwas vorschreiben, besonders wenn es die eigene handfeste Unabh\u00e4ngigkeit einschr\u00e4nken w\u00fcrde." },
  { code:"SO8", text:"Ger\u00e4t jemand in seiner Gruppe unter Druck, stellt er sich unaufgefordert sch\u00fctzend davor \u2013 seine St\u00e4rke zeigt sich weniger im eigenen Vorteil als im Einstehen f\u00fcr andere, denen er sich loyal verbunden f\u00fchlt. Kontrolle \u00fcbernimmt er dabei oft ganz selbstverst\u00e4ndlich, ohne dass ihm das selbst bewusst w\u00e4re." },
  { code:"SX8", text:"In einer engen Beziehung beansprucht sie den anderen mit einer Intensit\u00e4t, die schnell wie ein Besitzanspruch wirkt, auch wenn es ihr eigentlich um vollst\u00e4ndige, ungeteilte Hingabe geht. Ein Kompromiss in der Mitte f\u00fchlt sich f\u00fcr sie oft schwerer aushaltbar an als ein offener, direkt ausgetragener Konflikt." },
  { code:"SE9", text:"Nach einem anstrengenden Tag greift er eher zu einer vertrauten Gewohnheit, als sich aktiv mit dem auseinanderzusetzen, was ihn eigentlich besch\u00e4ftigt. Seine innere Ruhe entsteht weniger durch echte Kl\u00e4rung als durch das bewusste Fernhalten von allem, was diese Ruhe st\u00f6ren k\u00f6nnte." },
  { code:"SO9", text:"In einer Gruppe \u00fcbernimmt sie bereitwillig Aufgaben, die sonst liegen bleiben w\u00fcrden, und stellt die eigene Meinung dabei oft unbemerkt zugunsten des Gemeinschaftsfriedens zur\u00fcck. Was sie selbst eigentlich will, tritt so weit in den Hintergrund, dass sie es sp\u00e4ter kaum noch benennen kann." },
  { code:"SX9", text:"In einer engen Beziehung \u00fcbernimmt sie auff\u00e4llig oft die Vorlieben, Interessen und sogar den Tagesrhythmus des Partners, bis die Grenze zwischen eigenen und geteilten W\u00fcnschen kaum noch sp\u00fcrbar ist. F\u00fcr sie f\u00fchlt sich vollst\u00e4ndige Verschmelzung mit einer geliebten Person eher wie Erf\u00fcllung an als wie ein Verlust der eigenen Identit\u00e4t." },
];

const SQUIZ_TOTAL_ROUNDS = 10;
const SQUIZ_LEVEL_META = {
  1: { label: "Subtyp-Motivationsquiz I", sub: "Anf\u00e4nger \u00b7 nur der Grundtyp z\u00e4hlt",
       rule: "Sie lesen eine kurze Verhaltensszene, die ausschlie\u00dflich die <strong>Motivation</strong> hinter dem Handeln zeigt (nicht Fl\u00fcgel-, Stresspunkt- oder allgemeines Verhalten). Vier Antwortm\u00f6glichkeiten, jede ein <strong>Grundtyp (1&ndash;9)</strong> \u2013 die Instinktvariante spielt keine Rolle." },
  2: { label: "Subtyp-Motivationsquiz II", sub: "Experten \u00b7 voller Subtyp (Instinkt+Typ)",
       rule: "Sie lesen dieselben Szenen wie in Stufe I, doch die vier Antwortm\u00f6glichkeiten zeigen nun jeweils den <strong>vollen Subtyp</strong> (z. B. SO4). Gefragt ist die exakte Kombination aus Instinktvariante und Typ \u2013 deutlich anspruchsvoller." },
};

let _squizState = null;
let _squizLastLevel = 1;

function _squizBestKey(level) { return "kompass:squizBest:" + level; }
function _squizSaveBest(level, score) {
  try {
    const prev = parseInt(localStorage.getItem(_squizBestKey(level)) || "0", 10);
    if (score > prev) localStorage.setItem(_squizBestKey(level), String(score));
  } catch (e) {}
}
function _squizGetBest(level) {
  try { return parseInt(localStorage.getItem(_squizBestKey(level)) || "0", 10); } catch (e) { return 0; }
}
function _squizRerender() {
  if (location.hash === "#subtyp-motivationsquiz") { render(); } else { location.hash = "subtyp-motivationsquiz"; }
}
function _squizShuffle(arr) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; }
  return a;
}

function _squizPickQuestion(level, usedCodes) {
  const pool = SUBTYP_MOTIVATION.filter(s => !usedCodes.has(s.code));
  const source = pool.length ? pool : SUBTYP_MOTIVATION;
  const item = _squizShuffle(source)[0];
  const correctKey = level === 1 ? item.code.slice(2) : item.code;
  let distractPool;
  if (level === 1) {
    distractPool = ["1","2","3","4","5","6","7","8","9"].filter(n => n !== correctKey);
  } else {
    distractPool = SUBTYP_MOTIVATION.map(s => s.code).filter(c => c !== correctKey);
  }
  const distractors = _squizShuffle(distractPool).slice(0, 3);
  const options = _squizShuffle([correctKey, ...distractors]);
  return { item, correctKey, options };
}

function _squizNextRound() {
  const st = _squizState;
  if (!st) return;
  st.round += 1;
  if (st.round > SQUIZ_TOTAL_ROUNDS) {
    st.phase = "gameOver";
    _squizSaveBest(st.level, st.score);
    _squizRerender();
    return;
  }
  const q = _squizPickQuestion(st.level, st.usedCodes);
  st.usedCodes.add(q.item.code);
  st.question = q;
  st.answered = false;
  st.selectedKey = null;
  st.phase = "question";
  _squizRerender();
}

window._squizStart = function (level) {
  const lvl = SQUIZ_LEVEL_META[level] ? level : 1;
  _squizLastLevel = lvl;
  _squizState = { level: lvl, phase: "question", round: 0, score: 0, question: null, answered: false, selectedKey: null, usedCodes: new Set() };
  _squizNextRound();
};
window._squizSwitchLevel = function (level) {
  const lvl = SQUIZ_LEVEL_META[level] ? level : 1;
  _squizLastLevel = lvl;
  _squizState = null;
  _squizRerender();
};
window._squizAnswer = function (key) {
  const st = _squizState;
  if (!st || st.phase !== "question" || st.answered) return;
  st.answered = true;
  st.selectedKey = key;
  if (key === st.question.correctKey) st.score += 1;
  _squizRerender();
};
window._squizNextRound = function () { _squizNextRound(); };
window._squizRestart = function () {
  const lvl = _squizState ? _squizState.level : 1;
  window._squizStart(lvl);
};

function _squizLevelSwitcher(currentLevel) {
  const items = [1,2].map(l => {
    const active = l === currentLevel;
    return active
      ? `<span class="mem-level-pill mem-level-pill--active">${l===1?"I":"II"}</span>`
      : `<a href="javascript:void(0)" class="mem-level-pill" onclick="window._squizSwitchLevel(${l})">${l===1?"I":"II"}</a>`;
  }).join("");
  return `<div class="mem-level-switcher"><span class="mem-level-switcher-label">Stufe:</span>${items}</div>`;
}

function _squizKeyLabel(key, level) {
  return level === 1 ? "Typ " + key : key;
}

function _squizIntroScreen(level) {
  const meta = SQUIZ_LEVEL_META[level];
  const best = _squizGetBest(level);
  return shell(`
    <div class="page-container">
      ${pageHeader("wissen")}
      <div class="page-content">
        <p class="eyebrow">Wissen &middot; ${meta.label}</p>
        <h1 class="section-title">${meta.label}</h1>
        ${_squizLevelSwitcher(level)}
        <p class="psycho-intro">Eine kurze Alltagsszene, die ausschlie\u00dflich <strong>motivationsbedingtes Verhalten</strong> zeigt \u2013 vier Antwortm\u00f6glichkeiten, sofortiges Feedback, 10 Fragen pro Runde.</p>
        <div class="flash-rule-box">
          <p class="flash-rule-box-label">Was ist motivationsbedingtes Verhalten \u2013 und warum ist das schwerer, als es klingt?</p>
          <p style="margin:0 0 .6rem;">Jeder Subtyp hat eine <strong>Leidenschaft</strong> \u2013 den inneren Antrieb, der erkl\u00e4rt, <em>warum</em> jemand etwas tut, nicht nur, <em>was</em> er tut. Motivationsbedingtes Verhalten ist genau dieses Warum, sichtbar gemacht in einer konkreten Szene: die SO7 stellt ihre Begeisterung in den Dienst einer Vision \u2013 nicht weil sie introvertiert w\u00e4re, sondern weil sie ihre V\u00f6llerei so vor sich selbst rechtfertigt.</p>
          <p style="margin:0 0 .6rem;">Genau das macht die Typisierung in der Praxis schwer: Ein und dasselbe \u00e4u\u00dfere Verhalten kann ganz unterschiedliche Ursachen haben. Zur\u00fcckhaltung in einer Gruppe kann Motivation sein (SE5-R\u00fcckzug), kann aber genauso gut Fl\u00fcgeleinfluss (ein starker F\u00fcnferfl\u00fcgel bei einem anderen Typ), Stresspunkt-Verhalten oder schlicht Tagesform sein. Nur wer die Motivation \u2013 das Warum hinter der Handlung \u2013 von diesen anderen Faktoren unterscheiden kann, typisiert wirklich zuverl\u00e4ssig statt nur zu raten.</p>
          <p class="flash-rule-box-label" style="margin-top:.9rem;">Wonach wird in dieser Stufe gefragt?</p>
          <p style="margin:0;">${meta.rule}</p>
        </div>
        ${best > 0 ? `<p style="text-align:center;color:var(--muted);font-size:0.9rem;margin-bottom:1.2rem;">Ihre Bestleistung in dieser Stufe: <strong style="color:var(--ink);">${best}/${SQUIZ_TOTAL_ROUNDS}</strong></p>` : ""}
        <div style="text-align:center;">
          <button class="flash-btn" onclick="window._squizStart(${level})">Quiz starten &rarr;</button>
        </div>
      </div>
      ${_flashStyles()}
    </div>
  `);
}

function _squizQuestionScreen() {
  const st = _squizState;
  const meta = SQUIZ_LEVEL_META[st.level];
  const q = st.question;
  const optionsHtml = q.options.map(key => {
    const display = _squizKeyLabel(key, st.level);
    let cls = "flash-opt";
    let disabled = st.answered ? "disabled" : "";
    if (st.answered) {
      if (key === q.correctKey) cls += " flash-opt--correct";
      else if (key === st.selectedKey) cls += " flash-opt--wrong";
    }
    const onclick = st.answered ? "" : ` onclick="window._squizAnswer('${key}')"`;
    return `<button class="${cls}" ${disabled}${onclick}>${display}</button>`;
  }).join("");

  let feedback = "";
  if (st.answered) {
    const correct = st.selectedKey === q.correctKey;
    const isLast = st.round >= SQUIZ_TOTAL_ROUNDS;
    feedback = `
      <div class="flash-feedback">
        <p><strong>${correct ? "Richtig!" : "Leider falsch."}</strong></p>
        <div class="flash-name-reveal">${_squizKeyLabel(q.correctKey, st.level)} (${q.item.code})</div>
        <button class="flash-btn" onclick="window._squizNextRound()">${isLast ? "Endergebnis &rarr;" : "N\u00e4chste Frage &rarr;"}</button>
      </div>
    `;
  }

  return shell(`
    <div class="page-container">
      ${pageHeader("wissen")}
      <div class="page-content">
        <p class="eyebrow">Wissen &middot; ${meta.label}</p>
        <h1 class="section-title">${meta.label}</h1>
        ${_squizLevelSwitcher(st.level)}
        <div class="flash-hud">
          <span>Frage <strong>${st.round}</strong> / ${SQUIZ_TOTAL_ROUNDS}</span>
          <span>Punkte: <strong>${st.score}</strong></span>
        </div>
        <div style="background:linear-gradient(135deg,#2c2c2c,#1e1e1e);border-radius:14px;padding:1.6rem 1.4rem;margin:1rem 0 1.2rem;">
          <p style="color:#f5e9d0;font-family:'EB Garamond',Georgia,serif;font-size:1.05rem;line-height:1.6;margin:0;">${q.item.text}</p>
        </div>
        <p style="text-align:center;color:var(--muted);font-size:0.85rem;">${st.level === 1 ? "Welcher Grundtyp handelt hier aus seiner Motivation heraus?" : "Welcher volle Subtyp handelt hier aus seiner Motivation heraus?"}</p>
        <div class="flash-options">${optionsHtml}</div>
        ${feedback}
      </div>
      ${_flashStyles()}
    </div>
  `);
}

function _squizGameOverScreen() {
  const st = _squizState;
  const meta = SQUIZ_LEVEL_META[st.level];
  const best = _squizGetBest(st.level);
  const pct = Math.round((st.score / SQUIZ_TOTAL_ROUNDS) * 100);
  let msg;
  if (pct >= 90) msg = "Au\u00dfergew\u00f6hnlich &ndash; Sie erkennen die Motivation hinter dem Verhalten sicher!";
  else if (pct >= 70) msg = "Sehr gut! Sie unterscheiden Motivation bereits klar von allgemeinem Verhalten.";
  else if (pct >= 40) msg = "Solide Runde &ndash; die Unterscheidung von Motivation und allgemeinem Verhalten braucht \u00dcbung.";
  else msg = "Ein Anfang &ndash; motivationsbedingtes Verhalten von Fl\u00fcgel- oder Stresspunktverhalten zu trennen, ist anspruchsvoll. Nochmal versuchen?";
  return shell(`
    <div class="page-container">
      ${pageHeader("wissen")}
      <div class="page-content" style="text-align:center;">
        <p class="eyebrow">Wissen &middot; ${meta.label}</p>
        <h1 class="section-title">${st.score} von ${SQUIZ_TOTAL_ROUNDS} richtig</h1>
        ${_squizLevelSwitcher(st.level)}
        <p style="color:var(--muted);margin:0 0 0.8rem;">${pct}&thinsp;%</p>
        <p style="max-width:420px;margin:0 auto 1rem;">${msg}</p>
        <p style="color:var(--muted);font-size:0.9rem;margin-bottom:2rem;">Bestleistung in dieser Stufe: <strong style="color:var(--ink);">${best}/${SQUIZ_TOTAL_ROUNDS}</strong></p>
        <button class="flash-btn" onclick="window._squizRestart()">Neue Runde &rarr;</button>
      </div>
      ${_flashStyles()}
    </div>
  `);
}

function subtypMotivationsQuizPage() {
  if (!_squizState) return _squizIntroScreen(_squizLastLevel);
  if (_squizState.phase === "gameOver") return _squizGameOverScreen();
  return _squizQuestionScreen();
}

